'use strict';
const seasonNames=['Mùa xuân','Mùa hạ','Mùa thu','Mùa đông'];
const weatherDefs={clear:{name:'Trời quang',icon:'☀️',growth:1},cloud:{name:'Nhiều mây',icon:'☁️',growth:1},rain:{name:'Mưa',icon:'🌧️',growth:1.6},storm:{name:'Giông',icon:'⛈️',growth:1.3},heat:{name:'Nắng nóng',icon:'🌡️',growth:.25},wind:{name:'Gió mạnh',icon:'🌬️',growth:.8},snow:{name:'Tuyết',icon:'❄️',growth:.3}};
const seasonWeather=[['rain','rain','rain','clear','cloud'],['clear','clear','heat','heat','storm','rain'],['cloud','cloud','wind','wind','rain'],['snow','snow','snow','cloud','clear']];
const talentDefs={mining:{name:'Bàn tay khoáng thạch',icon:'⛏️',description:'Khai thác nhanh hơn 40%.'},harvest:{name:'Mầm sống',icon:'🌱',description:'Tăng thêm lương thực khi làm nông.'},sage:{name:'Trí tuệ thiên bẩm',icon:'📖',description:'Giúp khu định cư nghiên cứu nhanh hơn.'},healer:{name:'Dòng máu chữa lành',icon:'💚',description:'Hồi phục cho bản thân và người cùng khu định cư ở gần.'},guardian:{name:'Hộ vệ',icon:'🛡️',description:'Giảm 25% sát thương nhận.'},frost:{name:'Con của mùa đông',icon:'❄️',description:'Miễn tổn thương do lạnh và tuyết.'},sun:{name:'Con của mặt trời',icon:'☀️',description:'Miễn đói thêm do nắng nóng.'},swift:{name:'Bước chân gió',icon:'🪽',description:'Di chuyển nhanh hơn 25%.'}};
const seasonOld={newWorld,spawn,enrich,simulate,ecology,draw,showSelection,snapshot,restore,damage,miningStep};
let climate={enabled:true,season:Math.floor(simTime/5)%4,remaining:0,fronts:[]},weatherTick=0,creatingSeasonWorld=false;
const currentSeason=()=>typeof calendarTime==='undefined'?Math.floor(simTime/5)%4:seasonForTime(calendarTime);
function rollWeather(season){const list=seasonWeather[season];return list[Math.floor(random()*list.length)];}
function refreshWeather(log=true){const changed=climate.season!==currentSeason();climate.season=currentSeason();climate.remaining=typeof GAME_DAY_SECONDS==='undefined'?2.5+random()*2:100+random()*200;climate.fronts=Array.from({length:3},(_,i)=>({x:(i+.5)*W/3+random()*12-6,y:12+random()*(H-24),r:16+random()*10,type:rollWeather(climate.season),drift:(random()-.5)*(typeof GAME_DAY_SECONDS==='undefined'?1.5:.025)}));if(log&&changed)remember(seasonNames[climate.season]+' đến: thời tiết và sức sinh trưởng của đất thay đổi.','civil');renderClimateHud();}
function weatherAt(x,y){if(!climate.enabled)return 'clear';const front=climate.fronts.find(f=>Math.hypot(x-f.x,y-f.y)<f.r);return front?.type||'clear';}
function assignTalent(e){if(e.kind!=='human')return;if(!Object.hasOwn(talentDefs,e.talent)){const keys=Object.keys(talentDefs);e.talent=keys[Math.floor(random()*keys.length)];}e.destiny??={chosen:false,level:1,xp:0,lastKills:e.kills||0};}
function awakenHero(e,announce=true){if(!e||e.kind!=='human'||e.destiny?.chosen)return false;assignTalent(e);e.destiny.chosen=true;e.hp=100;e.hunger=100;if(announce)remember('★ '+e.name+' ('+raceNames[e.race]+') được trời chọn làm anh hùng bảo hộ.','divine');return true;}
function initializeDestinies(ensureHero=false){for(const e of humans())assignTalent(e);if(ensureHero&&!humans().some(e=>e.destiny.chosen)){const adults=humans().filter(e=>e.age>=2);if(adults.length)awakenHero(adults[Math.floor(random()*adults.length)],!creatingSeasonWorld);}}
enrich=function(e,race){seasonOld.enrich(e,race);assignTalent(e);};
spawn=function(...args){const e=seasonOld.spawn(...args);if(e?.kind==='human'){assignTalent(e);if(birthContext&&e.parents?.length&&random()<.3){const p=entities.find(p=>p.id===e.parents[0]);if(p?.talent)e.talent=p.talent;}if(!creatingSeasonWorld&&humans().filter(p=>p.destiny?.chosen).length<3&&random()<.025)awakenHero(e);}return e;};
newWorld=function(...args){creatingSeasonWorld=true;climate={enabled:true,season:0,remaining:0,fronts:[]};weatherTick=0;seasonOld.newWorld(...args);creatingSeasonWorld=false;initializeDestinies(true);refreshWeather(false);renderClimateHud();};
damage=function(e,value){assignTalent(e);seasonOld.damage(e,value*(e.talent==='guardian'?.75:1)*(e.destiny?.chosen?.7:1));};
miningStep=function(e,v,dt){seasonOld.miningStep(e,v,dt*(e.talent==='mining'?1.4:1));};
function weatherStep(dt){for(const f of climate.fronts)f.x=limit(f.x+f.drift*dt,0,W-.001);for(const e of humans()){assignTalent(e);const type=weatherAt(e.x,e.y),sheltered=typeof isResidentIndoors==='function'?isResidentIndoors(e):houses.some(h=>h.village===e.village&&Math.hypot(h.x-e.x,h.y-e.y)<3);if(laws.disasters&&!sheltered){if(type==='snow'&&e.talent!=='frost')damage(e,dt*.18);if(type==='heat'&&e.talent!=='sun')e.hunger=Math.max(-10000,e.hunger-dt*.3);}
if(e.talent==='healer'){e.hp=Math.min(100,e.hp+dt*.25);for(const p of humans())if(p.id!==e.id&&p.village===e.village&&Math.hypot(p.x-e.x,p.y-e.y)<3)p.hp=Math.min(100,p.hp+dt*.12);}
const v=villages.find(v=>v.id===e.village);if(v){if(e.talent==='sage')v.knowledge=Math.min(2000,v.knowledge+dt*(typeof mindFor==='function'?.004:.3));if(e.talent==='harvest'&&e.job==='farmer'&&(typeof isOnDuty!=='function'||isOnDuty(e))&&[1,5].includes(grid[idx(e.x,e.y)].t))v.food=Math.min(10000,v.food+dt*.5);}
if(e.destiny.chosen){let protection=0;for(const p of humans())if(p.id!==e.id&&p.village===e.village&&Math.hypot(p.x-e.x,p.y-e.y)<4&&p.hp<100){const amount=Math.min(100-p.hp,dt*(.15+e.destiny.level*.03));p.hp+=amount;protection+=amount;}e.destiny.xp+=Math.max(0,e.kills-e.destiny.lastKills)*5+protection*.15;e.destiny.lastKills=e.kills;while(e.destiny.level<10&&e.destiny.xp>=e.destiny.level*8){e.destiny.xp-=e.destiny.level*8;e.destiny.level++;remember('★ '+e.name+' trở thành anh hùng cấp '+e.destiny.level+'.','divine');}}
if(typeof mindFor!=='function'&&['storm','snow'].includes(type)&&!sheltered&&!e.soldier&&e.id!==possessed&&e.hunger>65){const home=houses.filter(h=>h.village===e.village).sort((a,b)=>Math.hypot(a.x-e.x,a.y-e.y)-Math.hypot(b.x-e.x,b.y-e.y))[0];if(home){const next=pathStep(e,home,false);if(next){e.tx=next.x;e.ty=next.y;}}}}
if(climate.enabled&&laws.disasters)for(const f of climate.fronts)if(f.type==='storm'&&random()<(typeof GAME_DAY_SECONDS==='undefined'?.08:.08/60)){const p=findLand(f.x+(random()-.5)*f.r,f.y+(random()-.5)*f.r);if(p){effect('lightning',p.x,p.y,2);for(const e of entities)if(Math.hypot(e.x-p.x,e.y-p.y)<2)damage(e,8);const t=grid[idx(p.x,p.y)];if(t.t===3||t.t===5)t.fire=Math.max(t.fire,5);}}
entities=entities.filter(e=>e.hp>0);renderClimateHud();if($('climate-dialog').open)renderClimatePanel();}
simulate=function(dt){const heroes=humans().filter(e=>e.destiny?.chosen).map(e=>({id:e.id,name:e.name})),positions=humans().filter(e=>e.talent==='swift'&&e.id!==possessed&&typeof mindFor!=='function').map(e=>({e,x:e.x,y:e.y}));seasonOld.simulate(dt);for(const p of positions){if(p.e.hp<=0)continue;const x=p.e.x+(p.e.x-p.x)*.25,y=p.e.y+(p.e.y-p.y)*.25;if(walkable(x,y)){p.e.x=x;p.e.y=y;}}for(const hero of heroes)if(!entities.some(e=>e.id===hero.id))remember('★ Anh hùng '+hero.name+' đã ngã xuống. Thế giới ghi nhớ người.','divine');climate.remaining-=dt;if(climate.season!==currentSeason()||climate.remaining<=0)refreshWeather();weatherTick+=dt;while(weatherTick>=1){weatherTick--;weatherStep(1);}};
ecology=function(){const before=grid.map(t=>t.food);seasonOld.ecology();const seasonal=[1.35,1.1,.8,.35][currentSeason()];for(let i=0;i<N;i++){const t=grid[i],type=weatherAt(i%W,Math.floor(i/W)),growth=t.food-before[i];if(growth>0)t.food=limit(before[i]+growth*seasonal*weatherDefs[type].growth,0,t.t===5?45:t.t===3?20:t.obj===3?25:8);if(['rain','storm','snow'].includes(type))t.fire=Math.max(0,t.fire-1.5);}};
draw=function(){seasonOld.draw();const s=base*zoom;ctx.save();ctx.translate((cw-W*s)/2+panX,(ch-H*s)/2+panY);ctx.scale(s,s);if(climate.enabled)for(const f of climate.fronts){if(f.type==='clear')continue;ctx.save();ctx.beginPath();ctx.arc(f.x,f.y,f.r,0,Math.PI*2);ctx.clip();ctx.fillStyle={snow:'#def5ff24',rain:'#4b8cce15',storm:'#26335c30',heat:'#f6bb5420',cloud:'#d7e3ed10',wind:'#c5dfd110'}[f.type];ctx.fillRect(f.x-f.r,f.y-f.r,f.r*2,f.r*2);const count=['rain','storm','snow'].includes(f.type)?70:18;for(let i=0;i<count;i++){const x=f.x-f.r+((i*7.73+(typeof animationTime==='function'?animationTime():simTime)*(f.type==='wind'?5:1))%(f.r*2)),y=f.y-f.r+((i*3.91+(typeof animationTime==='function'?animationTime():simTime)*(f.type==='snow'?1.7:8))%(f.r*2));ctx.fillStyle=f.type==='snow'?'#ecfaffb0':f.type==='heat'?'#ffc55760':'#a6d9ef80';ctx.fillRect(x,y,f.type==='snow'?.2:.08,f.type==='snow'?.2:.9);}ctx.restore();ctx.font='2px Segoe UI Emoji';ctx.textAlign='center';ctx.fillText(weatherDefs[f.type].icon,f.x,f.y-f.r*.7);}
for(const e of humans())if(e.destiny?.chosen&&!(typeof isResidentIndoors==='function'&&isResidentIndoors(e))){ctx.strokeStyle='#ffe290';ctx.lineWidth=.12;ctx.beginPath();ctx.arc(e.x,e.y,.9,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#ffe290';ctx.font='1.5px Segoe UI';ctx.textAlign='center';ctx.fillText('★',e.x,e.y-2);}ctx.restore();};
showSelection=function(id){seasonOld.showSelection(id);const e=entities.find(e=>e.id===id&&e.kind==='human');if(!e)return;assignTalent(e);const p=document.createElement('p');p.className='talent-detail';p.textContent=talentDefs[e.talent].icon+' Thiên phú: '+talentDefs[e.talent].name+' — '+talentDefs[e.talent].description;if(e.destiny.chosen)p.textContent+=' ★ Anh hùng trời ban · Cấp '+e.destiny.level+' · '+Math.floor(e.destiny.xp)+'/'+e.destiny.level*8+' kinh nghiệm.';$('selection').append(p);};
function renderClimateHud(){const b=$('climate-open');if(b)b.textContent='🌦 '+seasonNames[currentSeason()]+' · '+(climate.enabled?weatherDefs[climate.fronts[0]?.type||'clear'].name:'Thời tiết tắt');}
function focusChosen(id){const e=entities.find(e=>e.id===Number(id)&&e.destiny?.chosen);if(!e)throw Error('Anh hùng không còn tồn tại.');selectedId=e.id;setZoom(Math.max(zoom,2));const s=base*zoom;panX=(W/2-e.x)*s+Math.min(100,cw*.2);panY=(H/2-e.y)*s;showSelection(e.id);}
function renderClimatePanel(){$('natural-weather').checked=climate.enabled;$('climate-description').textContent=seasonNames[currentSeason()]+' · Một năm có 4 mùa (20 giây mô phỏng). Xuân cây cỏ phát triển mạnh; đông phát triển chậm. Mưa dập lửa và tăng sinh trưởng. Tuyết/nắng nóng gây lạnh/đói thêm ngoài nhà; tắt luật Thiên tai để ngăn tác hại và sét.';$('weather-regions').replaceChildren();for(const [i,f] of climate.fronts.entries()){const p=document.createElement('p');p.textContent=weatherDefs[f.type].icon+' Vùng '+(i+1)+': '+weatherDefs[f.type].name+' · tọa độ '+Math.floor(f.x)+', '+Math.floor(f.y);$('weather-regions').append(p);}const list=$('chosen-list');list.replaceChildren();for(const e of humans().filter(e=>e.destiny.chosen)){const article=document.createElement('article'),text=document.createElement('p'),button=document.createElement('button');text.textContent='★ '+e.name+' · '+raceNames[e.race]+' · Cấp '+e.destiny.level+' · '+talentDefs[e.talent].name;button.textContent='Tìm trên bản đồ';button.onclick=()=>{focusChosen(e.id);$('climate-dialog').close();};article.append(text,button);list.append(article);}if(!list.children.length){const p=document.createElement('p');p.textContent='Chưa có anh hùng còn sống. Cư dân mới có cơ hội hiếm được trời chọn.';list.append(p);}}
function buildClimateUI(){const b=document.createElement('button');b.id='climate-open';b.textContent='🌦 Thời tiết';$('god-open').parentElement.append(b);const holder=document.createElement('div');holder.innerHTML='<dialog id="climate-dialog" class="wide-dialog"><button class="close" aria-label="Đóng">×</button><span class="dialog-kicker">MÙA ĐỔI • THIÊN MỆNH THỨC GIẤC</span><h2>Thời tiết & thiên phú</h2><label class="law-row"><input type="checkbox" id="natural-weather" checked><span>Thời tiết tự nhiên ngẫu nhiên</span></label><p id="climate-description"></p><div id="weather-regions"></div><h3>★ Những người được chọn</h3><p>Anh hùng có sức chiến đấu cao, chịu đòn tốt và hồi phục cho cư dân gần họ. Chiến công và bảo hộ giúp tăng cấp. Dấu sao vàng đánh dấu họ trên bản đồ. Mỗi cư dân có một trong tám thiên phú; xem bằng Khám phá.</p><div id="chosen-list"></div></dialog>';document.body.append(holder);holder.querySelector('.close').onclick=()=>$('climate-dialog').close();b.onclick=()=>{renderClimatePanel();$('climate-dialog').showModal();};$('natural-weather').onchange=e=>setNaturalWeather(e.target.checked);}
function setNaturalWeather(enabled){if(typeof enabled!=='boolean')throw Error('Giá trị bật/tắt không hợp lệ.');climate.enabled=enabled;renderClimateHud();}
function destinyAttack(e){return e.destiny?.chosen?1.4+e.destiny.level*.06:1;}
snapshot=function(){return{...seasonOld.snapshot(),version:4,climate:JSON.parse(JSON.stringify(climate))};};
function validateSeasons(d){
const finite=(n,max)=>typeof n==='number'&&Number.isFinite(n)&&n>=0&&n<=max;
const c=d.climate;
if(!c||typeof c.enabled!=='boolean'||!Number.isInteger(c.season)||c.season<0||c.season>3||c.season!==(d.calendarSeconds===undefined?Math.floor(d.simTime/5)%4:seasonForTime(d.calendarSeconds))||!finite(c.remaining,d.calendarSeconds===undefined?5:360)||!Array.isArray(c.fronts)||c.fronts.length!==3)throw Error('Thời tiết trong bản lưu không hợp lệ.');
if(!c.fronts.every(f=>finite(f.x,W-.001)&&finite(f.y,H-.001)&&finite(f.r,30)&&f.r>=10&&Object.hasOwn(weatherDefs,f.type)&&Number.isFinite(f.drift)&&Math.abs(f.drift)<=1))throw Error('Vùng thời tiết không hợp lệ.');
if(!Array.isArray(d.entities)||!d.entities.every(e=>e.kind!=='human'||Object.hasOwn(talentDefs,e.talent)&&e.destiny&&typeof e.destiny.chosen==='boolean'&&Number.isInteger(e.destiny.level)&&e.destiny.level>=1&&e.destiny.level<=10&&finite(e.destiny.xp,1e9)&&finite(e.destiny.lastKills,1e9)))throw Error('Thiên mệnh trong bản lưu không hợp lệ.');
}
restore=function(input){const d=JSON.parse(JSON.stringify(input));if(!d||![1,2,3,4].includes(d.version))throw Error('Phiên bản không hỗ trợ.');const v=d.version;if(v===4){validateSeasons(d);d.version=3;}seasonOld.restore(d);if(v===4)climate=d.climate;else{climate={enabled:true,season:currentSeason(),remaining:0,fronts:[]};initializeDestinies(true);refreshWeather(false);}weatherTick=0;renderClimateHud();};
buildClimateUI();initializeDestinies(true);refreshWeather(false);
const seasonState=window.mamWorld.getState;
window.mamWorld={...window.mamWorld,newWorld:(...a)=>newWorld(...a),simulate:dt=>simulate(dt),ecology:()=>ecology(),snapshot:()=>snapshot(),restore:d=>restore(d),setNaturalWeather,getClimate:()=>JSON.parse(JSON.stringify({season:seasonNames[currentSeason()],...climate,heroes:humans().filter(e=>e.destiny.chosen).map(e=>({id:e.id,name:e.name,talent:e.talent,...e.destiny}))})),getState:()=>({...seasonState(),season:seasonNames[currentSeason()],weather:climate.fronts.map(f=>f.type),heroes:humans().filter(e=>e.destiny.chosen).length})};
if(document.modelContext?.registerTool)for(const t of [{name:'read_climate_and_heroes',description:'Read current season, local weather fronts and living chosen heroes.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>window.mamWorld.getClimate()},{name:'set_natural_weather',description:'Toggle random natural weather using the same control as the climate dialog.',inputSchema:{type:'object',properties:{enabled:{type:'boolean'}},required:['enabled'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{setNaturalWeather(input?.enabled);return window.mamWorld.getClimate();}}])try{Promise.resolve(document.modelContext.registerTool(t)).catch(()=>{});}catch{}
